<?php
namespace App\Models;
use App\Enums\FireEventStatus; use App\Enums\FireEventType; use App\Enums\Severity; use App\Models\Concerns\BelongsToFactory; use Illuminate\Database\Eloquent\Concerns\HasUlids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes;
class FireEvent extends Model { use HasUlids,SoftDeletes,BelongsToFactory; protected $fillable=['camera_id','zone_id','event_uuid','type','severity','status','confidence','detected_at','confirmed_at','resolved_at','false_alarm_at','confirmed_by','resolved_by','image_path','video_path','metadata']; protected function casts():array{return ['type'=>FireEventType::class,'severity'=>Severity::class,'status'=>FireEventStatus::class,'confidence'=>'decimal:4','detected_at'=>'datetime','confirmed_at'=>'datetime','resolved_at'=>'datetime','false_alarm_at'=>'datetime','metadata'=>'array'];} public function camera(){return $this->belongsTo(Camera::class);} public function zone(){return $this->belongsTo(Zone::class);} public function detections(){return $this->hasMany(FireEventDetection::class);} public function alerts(){return $this->hasMany(Alert::class);} public function notifications(){return $this->hasMany(Notification::class);} public function confirmedBy(){return $this->belongsTo(User::class,'confirmed_by');} public function resolvedBy(){return $this->belongsTo(User::class,'resolved_by');} }
